"""List-based pipeline: materializes a full list at every stage."""

import random


def make_records(n, seed=42):
    rng = random.Random(seed)
    return [{"id": i, "value": rng.random()} for i in range(n)]


def parse(records):
    return [dict(r) for r in records]


def filter_positive(records):
    return [r for r in records if r["value"] > 0.5]


def transform(records):
    return [{"id": r["id"], "value": r["value"] * 2} for r in records]


def aggregate(records):
    return sum(r["value"] for r in records)


def run(n=1_000_000):
    records = parse(make_records(n))
    records = filter_positive(records)
    records = transform(records)
    return aggregate(records)


if __name__ == "__main__":
    print(run())

