"""Generator-based pipeline: lazy, constant-memory at every stage."""

import random


def make_records(n, seed=42):
    def gen():
        rng = random.Random(seed)
        for i in range(n):
            yield {"id": i, "value": rng.random()}
    return gen()


def parse(records):
    for r in records:
        yield dict(r)


def filter_positive(records):
    for r in records:
        if r["value"] > 0.5:
            yield r


def transform(records):
    for r in records:
        yield {"id": r["id"], "value": r["value"] * 2}


def aggregate(records):
    total = 0.0
    for r in records:
        total += r["value"]
    return total


def run(n=1_000_000):
    stream = transform(filter_positive(parse(make_records(n))))
    return aggregate(stream)


if __name__ == "__main__":
    print(run())

